                var quoteHeadingMatch = Regex.Match(line, @"^#{1,6}\s+(.+?)(?:\s+#+)?$");
                var quoteHeading = quoteHeadingMatch.Success;
                quoteLines.Children.Add(DescriptionTextBlock(
                    quoteHeading ? quoteHeadingMatch.Groups[1].Value.Trim() : line,
                    quoteHeading ? 15 : 14,
                    quoteHeading,
                    0.86,
                    21));
                continue;
            }

